<template>
  <div class="flex flex-col gap-6">
    <div class="flex gap-4 items-center">
      <Button variant="outline" class="h-10 px-3" @click="onPlayAudio">
        <component :is="audioState === 'paused' ? Play : Pause" class="stroke-muted-foreground w-5 h-5" />
      </Button>
      <slot />
    </div>
    <div class="flex gap-4 items-center flex-wrap sm:gap-6">
      <audio
        ref="audio"
        :src="url"
        preload="metadata"
        @timeupdate="timeUpdate"
        @loadedmetadata="onLoadedMetadata"
        @loadeddata="onLoaded"
        @ended="onEnded"
      />
      <Slider
        :model-value="progress"
        :max="100"
        class="w-fit flex-auto min-w-64"
        @update:model-value="onProgressUpdate"
      />
      <p class="text-accent-foreground leading-7 min-w-24">
        {{ formatSecsToMins(currentTime) }}/{{ formatSecsToMins(duration) }}
      </p>
    </div>
  </div>
</template>

<script setup lang="ts">
import { Play, Pause } from 'lucide-vue-next';

interface Props {
  url: string;
}

const props = defineProps<Props>();

const audio = ref<HTMLAudioElement | null>(null);
const audioState = ref<'playing' | 'paused'>('paused');
const currentTime = ref<number>(0);
const duration = ref<number>(0);
const progress = ref<number[]>([0]);

function onLoadedMetadata(e: Event) {
  const target = e.target as HTMLAudioElement;
  if (target.duration && !isNaN(target.duration)) {
    duration.value = target.duration;
  }
}

function onLoaded(e: Event) {
  const target = e.target as HTMLAudioElement;
  if (target.duration && !isNaN(target.duration)) {
    duration.value = target.duration;
  }
}

function timeUpdate(e: Event) {
  const target = e.target as HTMLAudioElement;

  currentTime.value = target.currentTime;
  progress.value = [(currentTime.value / duration.value) * 100];
}

function onEnded() {
  audioState.value = 'paused';
}

function onProgressUpdate(data: number[] | undefined) {
  if (!audio.value || !data?.length) return;

  const percentage = data[0];
  progress.value = [percentage];
  currentTime.value = (percentage / 100) * duration.value;
  audio.value.currentTime = currentTime.value;
}

function onPlayAudio() {
  if (!audio.value) return;

  if (audioState.value === 'paused') {
    audio.value.play();
    audioState.value = 'playing';
  } else {
    audio.value.pause();
    audioState.value = 'paused';
  }
}
</script>

<style lang="scss" scoped></style>
